import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static int n, K, mod;
    static int[][] dpArr = new int[MAXN][20];
    static int[] cntArr = new int[MAXN];
    static int[] maxPow = new int[MAXN];
    static long[] factorial = new long[MAXN];
    static long[] invFactorial = new long[MAXN];

    static long quickPow(long base, int exp) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = res * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return res;
    }

    static long choose(int i, int j) {
        return factorial[i] * invFactorial[j] % mod * invFactorial[i - j] % mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        int totalAns = 0;

        if ((n & 1) == 1) {
            System.out.println(quickPow(K, n));
            sc.close();
            return;
        }

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % mod;
        }

        invFactorial[n] = quickPow(factorial[n], (int) (mod - 2));
        for (int i = n - 1; i >= 1; i--) {
            invFactorial[i] = invFactorial[i + 1] * (i + 1) % mod;
        }

        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    count++;
                }
            }
            cntArr[i] = count;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    maxPow[i] = 1 << j;
                    break;
                }
            }
        }

        for (int i = 0; i < MAXN; i++) {
            for (int j = 0; j < 20; j++) {
                dpArr[i][j] = 0;
            }
        }
        dpArr[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int rem = i ^ maxPow[i];
            for (int mask = rem; ; mask = (mask - 1) & rem) {
                int cur = mask + maxPow[i];
                int c2 = i ^ cur;
                int limit = Math.min(K - 1, cntArr[c2]);
                long tmpVal = choose(i, cur);
                for (int j = 0; j <= limit; j++) {
                    dpArr[i][j + 1] = (int) ((dpArr[i][j + 1] + (long) dpArr[c2][j] * tmpVal) % mod);
                }
                if (mask == 0) break;
            }
        }

        int maxJ = Math.min(cntArr[n], K);
        for (int j = 1; j <= maxJ; j++) {
            long val = (long) dpArr[n][j] * choose(K, j) % mod * factorial[j] % mod;
            totalAns = (int) ((totalAns + val) % mod);
        }

        long total = quickPow(K, n);
        totalAns = (int) ((total - totalAns + mod) % mod);
        System.out.println(totalAns);
        sc.close();
    }
}
